using Meili.Core.Models;
using Meili.Core.Time;
namespace Meili.App.Tests;
    public sealed class QuotePanelMarketData : Meili.Core.Abstractions.IMarketDataService
    {
        private readonly FakeMarketDataService _other=new();public int Bars;public bool Block;public int InFlight,MaxFlight;
        private static double Price(string s)=>s switch{"AAPL"=>356.27,"SPY"=>754.37,"QQQ"=>612.45,"MSFT"=>507.32,"NVDA"=>162.85,_=>421.06};
        private static double Delta(string s)=>s is "QQQ" or "NVDA"?-.67:.39;
        public bool RegularBarsOnly; public bool Overnight; public MarketState Phase = MarketState.Closed; public DateTimeOffset? Clock;
        private DateTime Date(){var now=MarketClock.ToEastern(Clock ?? DateTimeOffset.UtcNow);var day=now.Date;if(now.TimeOfDay<TimeSpan.FromHours(16))day=day.AddDays(-1);while(day.DayOfWeek is DayOfWeek.Saturday or DayOfWeek.Sunday)day=day.AddDays(-1);return day;}
        public Task<IReadOnlyList<Quote>> GetQuotesAsync(IReadOnlyList<string> symbols,CancellationToken ct=default)=>Task.FromResult<IReadOnlyList<Quote>>(symbols.Select(s=>FakeMarketDataService.MakeQuote(s,Price(s)) with{Name=s switch{"AAPL"=>"Apple Inc.","NVDA"=>"NVIDIA Corp.","MSFT"=>"Microsoft Corp.","SPY"=>"SPDR S&P 500 ETF",_=>s},Change=Price(s)-Price(s)/(1+Delta(s)/100),ChangePercent=Delta(s),PreviousClose=Price(s)/(1+Delta(s)/100),Open=Price(s)*.997,High=Price(s)*1.008,Low=Price(s)*.985,Volume=35120000,MarketState=Overnight?MarketState.Overnight:Phase,ExtendedPrice=Phase==MarketState.PreMarket?Price(s)*.99:Phase==MarketState.AfterHours?Price(s)*1.01:null,ExtendedChange=Phase==MarketState.PreMarket?-Price(s)*.01:Phase==MarketState.AfterHours?Price(s)*.01:null,ExtendedChangePercent=Phase==MarketState.PreMarket?-1:Phase==MarketState.AfterHours?1:null,ExtendedTime=Phase is MarketState.PreMarket or MarketState.AfterHours?(Clock??DateTimeOffset.UtcNow).AddMinutes(-1):null,FetchedAt=Clock??DateTimeOffset.UtcNow,AsOf=MarketClock.FromEastern(Date().AddHours(16)),DelayMinutes=15,IsRealtime=false}).ToArray());
        public async Task<BarSeries> GetBarsAsync(BarRequest request,CancellationToken ct=default){Bars++;if(Block){InFlight++;MaxFlight=Math.Max(MaxFlight,InFlight);try{await Task.Delay(Timeout.Infinite,ct);}finally{InFlight--;}}var at=MarketClock.ToEastern(Clock??DateTimeOffset.UtcNow);var start=MarketClock.FromEastern(Overnight?(at.Hour<4?at.Date.AddDays(-1):at.Date).AddHours(20):!RegularBarsOnly && (Phase is MarketState.PreMarket or MarketState.AfterHours)?at.Date.AddHours(Phase==MarketState.PreMarket?4:16):Date().AddHours(9.5));var seed=request.Symbol.Sum(c=>(int)c);var price=Price(request.Symbol)*(Phase==MarketState.PreMarket?.99:Phase==MarketState.AfterHours?1.01:1);var count=Phase is MarketState.PreMarket or MarketState.AfterHours?Math.Clamp((int)(((Clock??DateTimeOffset.UtcNow)-start).TotalMinutes/5),2,Overnight?96:78):78;return new BarSeries{Symbol=request.Symbol,Interval=request.Interval,Source="yahoo",DelayMinutes=15,AsOf=Phase is MarketState.PreMarket or MarketState.AfterHours && !RegularBarsOnly?start.AddMinutes((count-1)*5):start.AddHours(6.5),FetchedAt=Clock??DateTimeOffset.UtcNow,Bars=Enumerable.Range(0,count).Select(i=>Bar.CloseOnly(start.AddMinutes(i*5),price*(1+.003*Math.Sin(i*.19+seed)+Delta(request.Symbol)*.0001*i),1000)).ToArray()};}
        public Task<IReadOnlyList<DateOnly>> GetExpirationsAsync(string s,CancellationToken ct=default)=>_other.GetExpirationsAsync(s,ct);
